// 34:   def self.parse_xml(filename_or_xml, options={})
// 35:     listener = Listener.new(options)
// 36:     # parser = REXML::Parsers::StreamParser.new(File.new(filename), listener)
// 37:     parser = StreamParser.new(filename_or_xml, listener)
// 38:     parser.parse
// 39:     listener.result
// 40:   end
